import React, { useState, useEffect } from 'react';
import { Mail, Lock, ArrowRight, X, ArrowLeft, ShieldCheck, Zap, CheckCircle2, Save } from 'lucide-react';
import API from "../api/axios";
import { useNavigate } from "react-router-dom";

const EntryCard = ({ isOpen, onClose }) => {
  const navigate = useNavigate();

  const [isFlipped, setIsFlipped] = useState(false);
  const [loginView, setLoginView] = useState('login');
  const [loginOtpSent, setLoginOtpSent] = useState(false);

  const [signupStep, setSignupStep] = useState(1);
  const [signupOtpSent, setSignupOtpSent] = useState(false);

  // LOGIN
  const [loginEmail, setLoginEmail] = useState("");
  const [loginPassword, setLoginPassword] = useState("");
  const [loginError, setLoginError] = useState("");

  // FORGOT
  const [forgotEmail, setForgotEmail] = useState("");
  const [forgotOtp, setForgotOtp] = useState("");
  const [forgotError, setForgotError] = useState("");

  // SIGNUP
  const [signupEmail, setSignupEmail] = useState("");
  const [signupOtp, setSignupOtp] = useState("");
  const [signupName, setSignupName] = useState("");
  const [signupPhone, setSignupPhone] = useState("");
  const [signupPassword, setSignupPassword] = useState("");
  const [signupError, setSignupError] = useState("");

  useEffect(() => {
    if (!isOpen) {
      setIsFlipped(false);
      setLoginView('login');
      setLoginOtpSent(false);
      setSignupStep(1);
      setSignupOtpSent(false);

      setForgotEmail("");
      setForgotOtp("");
      setForgotError("");
    }
  }, [isOpen]);

  if (!isOpen) return null;

  // LOGIN
  const handleLogin = async () => {
    if (!loginEmail || !loginPassword) {
      setLoginError("Please fill email and password");
      return;
    }

    try {
      const res = await API.post("/auth/login", {
        email: loginEmail.trim().toLowerCase(),
        password: loginPassword,
      });

      localStorage.setItem("token", res.data.token);
      navigate("/dashboard");

    } catch (err) {
      setLoginError(err.response?.data?.message || "Invalid email or password");
    }
  };

  // FORGOT SEND OTP
  const handleForgotSendOtp = async () => {
    if (!forgotEmail) {
      setForgotError("Enter email");
      return;
    }

    try {
      await API.post("/auth/send-otp", {
        email: forgotEmail.trim().toLowerCase(),
      });

      setLoginOtpSent(true);
      setForgotOtp("");
      setForgotError("");

    } catch (err) {
      setForgotError(err.response?.data?.message || "Failed to send OTP");
    }
  };

  // FORGOT VERIFY OTP
  const handleForgotVerifyOtp = async () => {
    if (forgotOtp.length !== 6) {
      setForgotError("Enter full 6-digit OTP");
      return;
    }

    try {
      await API.post("/auth/verify-otp", {
        email: forgotEmail.trim().toLowerCase(),
        otp: forgotOtp,
      });

      setLoginView("reset-password");

    } catch {
      setForgotError("Invalid OTP");
    }
  };

  // SIGNUP SEND OTP
  const handleSendOtp = async () => {
    if (!signupEmail) {
      setSignupError("Email required");
      return;
    }

    try {
      await API.post("/auth/send-otp", {
        email: signupEmail.trim().toLowerCase(),
      });

      setSignupOtpSent(true);
      setSignupError("");

    } catch {
      setSignupError("Failed to send OTP");
    }
  };

  // SIGNUP VERIFY OTP
  const handleVerifyOtp = async () => {
    if (!signupOtp) {
      setSignupError("Enter OTP");
      return;
    }

    try {
      await API.post("/auth/verify-otp", {
        email: signupEmail.trim().toLowerCase(),
        otp: signupOtp.trim(),
      });

      setSignupStep(2);

    } catch {
      setSignupError("Invalid OTP");
    }
  };

  // SIGNUP FINAL
  const handleSignup = async () => {
    if (!signupName || !signupPhone || !signupPassword) {
      setSignupError("Fill all fields");
      return;
    }

    try {
      await API.post("/auth/register", {
        fullName: signupName,
        email: signupEmail.trim().toLowerCase(),
        password: signupPassword,
        phone: signupPhone,
        role: "CITIZEN",
      });

      setIsFlipped(false);
      setLoginView("login");

    } catch (err) {
      const msg = err.response?.data?.message || "";

      if (msg.toLowerCase().includes("exists")) {
        setSignupError("Account already exists. Redirecting to login...");

        setTimeout(() => {
          setIsFlipped(false);
          setLoginView("login");
        }, 1500);
      } else {
        setSignupError("Registration failed");
      }
    }
  };

  const goToSignup = () => {
    setIsFlipped(true);
    setSignupStep(1);
    setSignupOtpSent(false);
  };

  const goToSignin = () => {
    setIsFlipped(false);
    setLoginView('login');
    setLoginOtpSent(false);

    setForgotEmail("");
    setForgotOtp("");
    setForgotError("");
  };

  return (
    <div className="fixed inset-0 z-[100] flex items-center justify-center bg-[#47510B]/60 backdrop-blur-md p-4 font-sans">
      <div className="flip-container w-full max-w-[400px] h-[600px] animate-slide-up">
        <div className={`flip-inner ${isFlipped ? 'is-flipped' : ''}`}>

          <div className="flip-front bg-[#FDFAD8] border-4 border-[#47510B] rounded-[40px] shadow-[0_20px_0_0_#47510B] p-8 flex flex-col justify-between text-[#47510B]">

            {/* FORGOT PASSWORD FIXED */}
            {loginView === 'forgot' && (
              <div className="space-y-4">

                <input
                  type="email"
                  value={forgotEmail}
                  onChange={(e) => setForgotEmail(e.target.value)}
                  placeholder="REGISTERED_EMAIL"
                  className="w-full bg-white border-2 border-[#47510B] p-4 rounded-2xl font-bold text-sm"
                />

                {loginOtpSent && (
                  <div className="flex gap-2 justify-between">
                    {[...Array(6)].map((_, i) => (
                      <input
                        key={i}
                        type="text"
                        maxLength="1"
                        value={forgotOtp[i] || ""}
                        onChange={(e) => {
                          const val = e.target.value;
                          if (!/^[0-9]?$/.test(val)) return;

                          const arr = forgotOtp.split("");
                          arr[i] = val;
                          setForgotOtp(arr.join(""));
                        }}
                        className="w-12 h-14 bg-white border-2 border-[#47510B] rounded-xl text-center font-black text-xl"
                      />
                    ))}
                  </div>
                )}

                {forgotError && (
                  <p className="text-[#AB1717] text-xs text-center">
                    {forgotError}
                  </p>
                )}

                <button
                  type="button"
                  onClick={() => {
                    if (!loginOtpSent) handleForgotSendOtp();
                    else handleForgotVerifyOtp();
                  }}
                  className="w-full bg-[#AB1717] text-white font-black p-5 rounded-2xl shadow-[0_6px_0_0_#5E0E0E] active:translate-y-1 uppercase italic"
                >
                  {loginOtpSent ? 'Verify Code' : 'Request OTP'}
                </button>

              </div>
            )}

          </div>
        </div>
      </div>
    </div>
  );
};

export default EntryCard;
